// src/infra/repositories/conversationRepository.ts
class conversationRepository {
  async create(data) {
    const [conversation] = await db.insert(conversations).values(data).returning();
    return conversation;
  }
  async findById(id) {
    const [conversation] = await db.select().from(conversations).where(eq(conversations.id, id));
    return conversation;
  }
  async findByPhoneNumber(phoneNumber) {
    const [conversation] = await db.select().from(conversations).where(eq(conversations.phoneNumber, phoneNumber)).orderBy(desc(conversations.lastMessageAt)).limit(1);
    return conversation;
  }
  async update(id, data) {
    const [conversation] = await db.update(conversations).set({ ...data, updatedAt: new Date }).where(eq(conversations.id, id)).returning();
    return conversation;
  }
  async updateLastMessage(id) {
    const [conversation] = await db.update(conversations).set({
      lastMessageAt: new Date,
      updatedAt: new Date
    }).where(eq(conversations.id, id)).returning();
    return conversation;
  }
  async list(limit = 50, offset = 0) {
    return await db.select().from(conversations).orderBy(desc(conversations.lastMessageAt)).limit(limit).offset(offset);
  }
  async delete(id) {
    await db.delete(conversations).where(eq(conversations.id, id));
  }
}

// src/infra/repositories/messageRepository.ts
class messageRepository {
  async create(data) {
    const [message] = await db.insert(messages).values(data).returning();
    return message;
  }
  async findById(id) {
    const [message] = await db.select().from(messages).where(eq(messages.id, id));
    return message;
  }
  async findByWhatsAppId(whatsappMessageId) {
    const [message] = await db.select().from(messages).where(eq(messages.whatsappMessageId, whatsappMessageId));
    return message;
  }
  async findByConversationId(conversationId, limit = 50, offset = 0) {
    return await db.select().from(messages).where(eq(messages.conversationId, conversationId)).orderBy(desc(messages.createdAt)).limit(limit).offset(offset);
  }
  async update(id, data) {
    const [message] = await db.update(messages).set({ ...data, updatedAt: new Date }).where(eq(messages.id, id)).returning();
    return message;
  }
  async updateStatus(id, status) {
    const [message] = await db.update(messages).set({ status, updatedAt: new Date }).where(eq(messages.id, id)).returning();
    return message;
  }
  async list(limit = 50, offset = 0) {
    return await db.select().from(messages).orderBy(desc(messages.createdAt)).limit(limit).offset(offset);
  }
  async delete(id) {
    await db.delete(messages).where(eq(messages.id, id));
  }
}

